props : function props(e, onePerLine)
{
  if (e === null) {
    println(\%22props called with null argument\%22, \%22error\%22);
    return;
  }

  if (e === undefined) {
    println(\%22props called with undefined argument\%22, \%22error\%22);
    return;
  }

  var ns = [\%22Methods\%22, \%22Fields\%22, \%22Unreachables\%22];
